const DISPOSITIONS = ['Connected-Interested', 'Connected-NotInterested', 'Callback', 'NoAnswer', 'Busy', 'GatekeeperOnly', 'WrongNumber', 'VoicemailLeft', 'OptOut'];

const body = $input.first().json.body;
const { callNote, disposition } = body;

if (!callNote || typeof callNote !== 'string' || callNote.trim().length === 0) {
  return [{ json: { valid: false, reason: 'Call Note is required and cannot be empty.' } }];
}

if (!DISPOSITIONS.includes(disposition)) {
  return [{ json: { valid: false, reason: `Disposition is required and must be one of: ${DISPOSITIONS.join(', ')}.` } }];
}

return [{ json: { valid: true } }];
